def is_equal_to_sum_even(value):
    """Checks if the given integer can be expressed as the sum of two even numbers >= 4.
    Returns True if value is an even integer >= 8, False otherwise."""
    # Reject non-int types and booleans
    if not isinstance(value, int) or isinstance(value, bool):
        return False
    # Must be at least 8 and even
    if value < 8 or value % 2 != 0:
        return False
    return True

